 sealed class OwnedMessageAnswers:IDisposable {
  readonly nint owner;readonly uint thread;readonly Queue<int> answers;readonly System.Windows.Forms.Timer timer=new(){Interval=20};readonly HashSet<nint> allowedOwners=[];readonly HashSet<string> observed=[];
  public int Handled{get;private set;}
  public OwnedMessageAnswers(Form owner,params int[] buttons){Check(owner.IsHandleCreated&&ReferenceEquals(Control.FromHandle(owner.Handle),owner),"Message responder requires exact owned managed Form.");this.owner=owner.Handle;allowedOwners.Add(owner.Handle);if(owner.MdiParent is Form parent){Check(parent.IsHandleCreated&&ReferenceEquals(Control.FromHandle(parent.Handle),parent),"MDI prompt parent must be another exact owned managed Form.");allowedOwners.Add(parent.Handle);}thread=GetCurrentThreadId();answers=new(buttons);timer.Tick+=Tick;timer.Start();}
  void Tick(object? sender,EventArgs args){if(answers.Count==0)return;EnumThreadWindows(thread,(hwnd,_)=>{GetWindowThreadProcessId(hwnd,out var process);if(process!=Environment.ProcessId)return true;var name=new System.Text.StringBuilder(64);GetClassName(hwnd,name,64);if(name.ToString()!="#32770")return true;var observation=$"{hwnd}/{GetWindow(hwnd,4)}/{answers.Peek()}/{GetDlgItem(hwnd,1)}";if(observed.Add(observation))Samples.Add(new{name="own native dialog observation",thread,dialog=hwnd.ToInt64(),nativeOwner=GetWindow(hwnd,4).ToInt64(),expectedOwners=allowedOwners.Select(h=>h.ToInt64()).ToArray(),nextAnswer=answers.Peek(),okButton=GetDlgItem(hwnd,1).ToInt64(),yesButton=GetDlgItem(hwnd,6).ToInt64()});var owned=false;var depth=0;for(var next=GetWindow(hwnd,4);next!=0&&depth++<12;next=GetWindow(next,4))if(allowedOwners.Contains(next)){owned=true;break;}if(!owned)return true;var buttonId=answers.Peek();var button=GetDlgItem(hwnd,buttonId);if(button==0&&buttonId==1){var matches=new List<nint>();EnumChildWindows(hwnd,(candidate,_)=>{GetWindowThreadProcessId(candidate,out var cp);var cn=new System.Text.StringBuilder(64);GetClassName(candidate,cn,64);if(cp==Environment.ProcessId&&cn.ToString()=="Button"){var caption=new System.Text.StringBuilder(160);GetWindowText(candidate,caption,160);var text=caption.ToString().Replace("&","");var key=$"button/{hwnd}/{candidate}/{text}";if(observed.Add(key))Samples.Add(new{name="own default dialog button observation",dialog=hwnd.ToInt64(),button=candidate.ToInt64(),nativeControlId=GetDlgCtrlID(candidate),caption=text});if(text=="OK"||text.StartsWith("확인",StringComparison.Ordinal))matches.Add(candidate);}return true;},0);if(matches.Count==1)button=matches[0];}if(button==0||GetParent(button)!=hwnd)return true;GetWindowThreadProcessId(button,out var buttonProcess);if(buttonProcess!=Environment.ProcessId)return true;answers.Dequeue();Handled++;Samples.Add(new{name="owned native MessageBox answer",processId=Environment.ProcessId,ownerHandle=owner.ToInt64(),dialogHandle=hwnd.ToInt64(),buttonId,nativeButtonId=GetDlgCtrlID(button),scope="EnumThreadWindows of own UI thread; matching owner chain and process; BM_CLICK on exact dialog child only"});SendMessage(button,0x00f5,0,0);return false;},0);}
  public void Dispose(){timer.Stop();timer.Tick-=Tick;timer.Dispose();}
 }
 sealed class ControlledDocument: IWorkspaceDocument {
  public string Title=>"Synthetic async close document";public DocumentContext Context{get;private set;}=new(Guid.NewGuid().ToString("N"),"synthetic-lifecycle",null,"test-only");public Control View{get;}=new Panel();public Panel Left{get;}=new();public Panel Right{get;}=new();public bool IsDirty{get;private set;}=true;public bool FailSave{get;set;}public int Saves{get;private set;}
  public event EventHandler? TitleChanged{add{}remove{}}public event EventHandler? SelectionChanged{add{}remove{}}
  public void SetContext(DocumentContext context)=>Context=context;
  public async Task SaveAsync(CancellationToken ct=default){Saves++;Samples.Add(new{name="controlled save before await",fail=FailSave,thread=GetCurrentThreadId(),context=SynchronizationContext.Current?.GetType().FullName});await Task.Delay(220,ct);Samples.Add(new{name="controlled save after await",fail=FailSave,thread=GetCurrentThreadId(),context=SynchronizationContext.Current?.GetType().FullName});if(FailSave)throw new IOException("Explicit synthetic save failure");IsDirty=false;}
  public void MarkClean()=>IsDirty=false;
  public void Dispose(){View.Dispose();Left.Dispose();Right.Dispose();}
 }
 sealed class ControlledModule: IDesktopModule {
  public string ModuleId=>"synthetic-lifecycle";public string DisplayName=>"Synthetic test only";public string Version=>"test";public IReadOnlyList<RecordSchema> Schemas=>Array.Empty<RecordSchema>();public void Initialize(IWorkspaceServices services){}public IWorkspaceDocument CreateDocument(DocumentContext context)=>new ControlledDocument();public Control CreateLeftPanel(IWorkspaceDocument doc)=>((ControlledDocument)doc).Left;public Control CreateRightPanel(IWorkspaceDocument doc)=>((ControlledDocument)doc).Right;public void Activate(IWorkspaceDocument doc){}public void Deactivate(IWorkspaceDocument doc){}public void Dispose(){}
 }
 static async Task CheckPanelClampAsync(WorkbenchForm form){var prior=form.Bounds;try{form.Width=900;form.SetPanelWidths(600,600);form.PerformLayout();await Task.Delay(80);var center=Tree(form).OfType<MdiClient>().Single();Check(center.Width>=320,$"600+600 panels collapse center at900 width: {center.Width}");Check(form.LeftPanelWidth<600&&form.RightPanelWidth<600,"Panels were not proportionally constrained");Samples.Add(new{name="narrow panel clamp",width=form.Width,clientWidth=form.ClientSize.Width,left=form.LeftPanelWidth,right=form.RightPanelWidth,center=center.Width});}finally{form.Bounds=prior;form.SetPanelWidths(310,330);await Task.Delay(40);}}
 static void CheckFloatingFrameHidden(WorkbenchForm form){var frame=(Panel)typeof(WorkbenchForm).GetField("right",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(form)!;Check(!frame.Visible,"Empty docked inspector frame remained visible after floating");var floating=form.OwnedForms.Single(f=>f.Text.StartsWith("\uc18d\uc131 \ud328\ub110"));form.TogglePanel("right");Check(!floating.Visible,"Floating inspector did not follow hide command");form.TogglePanel("right");Check(floating.Visible,"Floating inspector did not follow show command");}
 static async Task LifecycleChecks(WorkbenchForm main,LocalWorkspace store,WorkspaceServices services){
  await Test("owned native dirty child Cancel preserves data and No discards without saving",async()=>{using var doc=new ControlledDocument();using var child=new DocumentForm(new ControlledModule(),doc);child.Show(main);using(var answers=new OwnedMessageAnswers(child,2)){child.Close();await Task.Delay(100);Check(answers.Handled==1&&!child.IsDisposed&&doc.IsDirty&&doc.Saves==0,"Cancel changed or closed the dirty child");}using(var answers=new OwnedMessageAnswers(child,7)){child.Close();await Until(()=>child.IsDisposed,"No did not close dirty child");Check(answers.Handled==1&&doc.Saves==0,"No unexpectedly saved dirty child");}});
  await Test("owned native dirty child Yes waits for one asynchronous save then closes",async()=>{using var doc=new ControlledDocument();using var child=new DocumentForm(new ControlledModule(),doc);child.Show(main);using var answers=new OwnedMessageAnswers(child,6);child.Close();Check(!child.IsDisposed,"Child closed before delayed save finished");await Until(()=>child.IsDisposed,"Async saved child needed a second close");Check(answers.Handled==1&&doc.Saves==1&&!doc.IsDirty,"Dirty child save was skipped or duplicated");});
  await Test("owned native save failure reports error and preserves dirty child",async()=>{using var doc=new ControlledDocument(){FailSave=true};using var child=new DocumentForm(new ControlledModule(),doc);child.Show(main);using(var answers=new OwnedMessageAnswers(child,6,1)){child.Close();try{await Until(()=>answers.Handled==2,"Failure message did not appear after Yes");}finally{Samples.Add(new{name="controlled failure final state",answers=answers.Handled,saves=doc.Saves,dirty=doc.IsDirty,disposed=child.IsDisposed,threadFault=ThreadFault?.GetType().Name});}await Task.Delay(70);Check(!child.IsDisposed&&doc.IsDirty&&doc.Saves==1,"Failed save closed or cleaned document");}doc.MarkClean();child.Close();await Until(()=>child.IsDisposed,"Controlled failed child cleanup did not close");});
  await Test("one Workbench Exit saves dirty child asynchronously and Cancel preserves owner plus floats",async()=>{using var catalog=DesktopModules.Load(Package);using var owner=new WorkbenchForm(Package,catalog,new WorkspaceServices(services.Actor,store,new ExplicitNoReports()));owner.Show(main);await owner.Ready;using var doc=new ControlledDocument();using var child=new DocumentForm(new ControlledModule(),doc){MdiParent=owner};child.Show();owner.ToggleFloating("right");using(var answers=new OwnedMessageAnswers(child,2)){owner.Close();await Task.Delay(110);Check(answers.Handled==1&&!owner.IsDisposed&&!child.IsDisposed&&doc.IsDirty,"Owner Cancel lost dirty document");Check(owner.OwnedForms.Any(f=>f.Text.StartsWith("\uc18d\uc131 \ud328\ub110")&&f.Visible),"Owner Cancel lost intended floating inspector");}using(var answers=new OwnedMessageAnswers(child,6)){owner.Close();await Until(()=>owner.IsDisposed,"One owner Exit did not finish after async Save");Check(answers.Handled==1&&doc.Saves==1&&!doc.IsDirty,"Owner Exit skipped/duplicated async save or requested another click");}});
 }
